INSERT INTO passages (id, source, ref, parent, part, heading, title, text, url, ord) VALUES ('act:sch2~1', 'act', 'Sch 2', 'act:sch2', 'Schedule 2', '', 'Schedule 2', 'Section 7
#### Part I—Exempt agencies
#### Division 1
Aboriginal Land Councils and Land Trusts
